create or replace function public.send_feedback_message(target_ticket_id bigint,target_body text) returns bigint language plpgsql security definer set search_path=public as $$ declare caller uuid:=auth.uid(); new_id bigint; begin if caller is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.account_status a where a.user_id=caller and a.status='ACTIVE') then raise exception 'active account required'; end if; if char_length(trim(coalesce(target_body,''))) not between 1 and 4000 then raise exception 'invalid body'; end if; if not exists(select 1 from public.feedback_tickets t where t.id=target_ticket_id and (t.user_id=caller or public.is_app_admin())) then raise exception 'feedback ticket not found'; end if; insert into public.feedback_messages(ticket_id,sender_id,body) values(target_ticket_id,caller,trim(target_body)) returning id into new_id; return new_id; end $$; revoke all on function public.send_feedback_message(bigint,text) from public,anon; grant execute on function public.send_feedback_message(bigint,text) to authenticated;